"""The VJ frame (native/vj.py): two decks, each a video source and a look,
their previews side by side, a crossfader between them, the mix on air in
place of the effect - in the sim, so on the stream.

    vj_ui.build(app); vj_ui.refresh(app); vj_ui.poll(app)    # as the other frames
    vj_ui.browse(app, i)                                     # the looks as moving thumbnails, for deck i
    vj_ui.undo(app, redo=False)                              # the VJ's last change undone (Ctrl+Z in the frame)
"""
# AI: below section was generated by an AI
import math
import os
import time

import dearpygui.dearpygui as dpg
import numpy as np

from native import num, typeface, vj, vj_looks, weight
from native.typeface import px

TAG = "vj_win"
BROWSE = "vj_browse_win"
PV_W, PV_H = 96, 72                       # a deck's preview texture (any canvas is fitted to it)
OUT_N = 64                                # the output's preview texture, square
TH_W, TH_H = 48, 36                       # a look's thumbnail in the browser
LETTER = ("A", "B", "C")
AUTO = (("off", "off"), ("bars", "every few bars"), ("sections", "at the show's sections"))
SAVE_AFTER = 0.4                          # s a change settles before it is saved (one undo step a drag)


def _c():
    from native import chrome
    return chrome


def look_names():
    """The looks in family order, then Effect."""
    out = []
    for fam, _ in vj_looks.FAMILIES:
        out += [n for n, lk in vj_looks.LOOKS.items() if lk.family == fam]
    return out + [vj.EFFECT]


def _tex(tag, w, h):
    from native.textures import registry
    if not dpg.does_item_exist(tag):
        dpg.add_dynamic_texture(w, h, [0.0] * (w * h * 4), tag=tag, parent=registry())


